#!/usr/bin/env bash
# E10.L, the learn tool (decision 63, TK-L): queue commands. NOT QUEUED by the agent that wrote them.
# Pre-registration: experiments/e10-self-semantics/e10-learn/preregistration.md (§9). Run from the repository root of the
# main checkout after merging this branch. The jobs are added through the queue's Python API (idempotent: an existing
# job name is skipped); `queue --dry-run` prints them without touching the queue.
#
# Every job is evaluation-only on existing (or, for T7, pending) checkpoints, inside the 54.4995 slot:
#   54.4995   GPU  T7 evidence extraction (C0' hidden states, seeds 1-3) + T7 store-entry and MeSH item vectors
#   54.49951  CPU  T7 erased-edge runs: arms c2 (primary, L4a / L4b), features, c5full (positive control) x seeds 1-3
#   54.49952  CPU  T7 MeSH placement (2025->2026 primary, >=1-abstract and 2024->2025 secondary) x seeds 1-3
#   54.49953  GPU/CPU  T1 MeSH placement (seed 1)
#   54.49954  GPU  T4 / T5 evidence extraction;   54.49955  CPU  T4 / T5 erased-edge runs
#   54.49956  GPU/CPU  WordNet: TaxoExpan SemEval noun/verb (primary), TMN (secondary); outputs local
#   54.49959  CPU  reports (names end in -report)
# T7 trains at 51-54 (seeds 1-3 due about 10-11 October), so its jobs sit behind its checkpoints in priority order.
# Estimates (idle GPU, from the CPU smoke; preregistration §9): about 1.85 GPU-h and 8.63 CPU-h, 78 jobs.
set -euo pipefail
cd "$(dirname "$0")/../../.."
PY=${PY:-$HOME/anaconda3/envs/vsa-repro/bin/python}
PYTHONPATH=src $PY -m vsa_embed.experiments.e10_learn queue --python "$PY"

